// Restart/reconnect anti-resurrection probes. These functions deliberately use
// Firestore server reads rather than cache reads; they expose only current source
// message IDs to the app controller and do not mutate Firebase state.
export async function readCloudMessageIdsFromServer(conversationId,myUid){const s=await ensureServices();if(!authUser||authUser.uid!==myUid)throw new Error("Sign in first.");const cid=String(conversationId||"").trim();if(!cid)throw new Error("Conversation is required.");const conv=await s.fsSdk.getDocFromServer(s.fsSdk.doc(s.db,"conversations",cid));if(!conv.exists())throw new Error("Conversation is not available to this account.");const members=Array.isArray(conv.data().members)?conv.data().members:[];if(!members.includes(myUid))throw new Error("Conversation is not available to this account.");const snap=await s.fsSdk.getDocsFromServer(s.fsSdk.collection(s.db,"conversations",cid,"messages"));return snap.docs.map(d=>d.id);}
export async function readCloudGroupMessageIdsFromServer(groupId){const s=await ensureServices();if(!authUser)throw new Error("Sign in first.");const gid=String(groupId||"").trim();if(!gid)throw new Error("Group is required.");const group=await s.fsSdk.getDocFromServer(s.fsSdk.doc(s.db,"groups",gid));if(!group.exists())throw new Error("Group is not available to this account.");const members=Array.isArray(group.data().memberUids)?group.data().memberUids:[];if(!members.includes(authUser.uid))throw new Error("Group is not available to this account.");const snap=await s.fsSdk.getDocsFromServer(s.fsSdk.collection(s.db,"groups",gid,"messages"));return snap.docs.map(d=>d.id);}

export async function uploadEncryptedAttachment({paths,manifest,chunks}){const s=await ensureServices();if(!authUser)throw new Error("Sign in first.");if(!paths?.manifest||!Array.isArray(paths.chunks)||paths.chunks.length!==chunks?.length)throw new Error("Invalid attachment upload plan.");const enc=new TextEncoder(),manifestRef=s.storageSdk.ref(s.storage,paths.manifest),chunkRefs=paths.chunks.map(path=>s.storageSdk.ref(s.storage,path));await s.storageSdk.uploadBytes(manifestRef,enc.encode(JSON.stringify(manifest)),{contentType:"application/json",customMetadata:{fidunioFormat:"attachment-v1"}});for(let i=0;i<chunks.length;i++)await s.storageSdk.uploadBytes(chunkRefs[i],enc.encode(JSON.stringify(chunks[i])),{contentType:"application/octet-stream",customMetadata:{fidunioFormat:"attachment-v1-ciphertext"}});await Promise.all([s.storageSdk.getMetadata(manifestRef),...chunkRefs.map(ref=>s.storageSdk.getMetadata(ref))]);return true;}

export async function downloadEncryptedAttachment(paths){const s=await ensureServices();if(!authUser)throw new Error("Sign in first.");if(!paths?.manifest||!Array.isArray(paths.chunks)||!paths.chunks.length)throw new Error("Invalid attachment download plan.");const read=async(path,label)=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const ref=s.storageSdk.ref(s.storage,path),url=await Promise.race([s.storageSdk.getDownloadURL(ref),new Promise((_,reject)=>setTimeout(()=>reject(Object.assign(new Error("URL lookup timed out"),{code:"storage/url-timeout"})),10000))]),response=await fetch(url,{cache:"no-store",signal:controller.signal});if(!response.ok)throw Object.assign(new Error(`HTTP ${response.status}`),{code:`storage/http-${response.status}`});const buffer=await response.arrayBuffer();if(buffer.byteLength>1048576)throw Object.assign(new Error("stored object exceeds limit"),{code:"storage/object-too-large"});try{return JSON.parse(new TextDecoder().decode(buffer));}catch{throw Object.assign(new Error("invalid stored data"),{code:"attachment/invalid-json"});}}catch(err){const code=err?.name==="AbortError"?"storage/fetch-timeout":String(err?.code||"storage/unknown");throw new Error(`${label} download failed (${code}): ${err?.message||"unknown error"}`,{cause:err});}finally{clearTimeout(timer);}};const manifest=await read(paths.manifest,"Manifest"),chunks=new Array(paths.chunks.length),workers=Math.min(6,paths.chunks.length);let next=0;await Promise.all(Array.from({length:workers},async()=>{while(next<paths.chunks.length){const index=next++;chunks[index]=await read(paths.chunks[index],`Chunk ${index+1}`);}}));return{manifest,chunks};}
